function pageTitle(){return ({agenda:'Agenda',cobrancas:'Cobranças',comandas:'Comandas',mensagens:'Mensagens pré-definidas',clientes:'Clientes & anamneses',servicos:'Serviços & pacotes',estoque:'Produtos & estoque',despesas:'Despesas',equipe:'Profissionais & comissão',performance:'Performance',financeiro:'Resumo financeiro',fidelidade:'Melhores clientes',configuracoes:'Configurações'})[page]||'Agenda'}
function heading(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${role==='manager'?'PAINEL DE GESTÃO':'ÁREA DO CLIENTE'}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${action}</div></div>`}
function btn(label,action,kind='primary',glyph='＋'){return `<button class="button ${kind}" data-action="${action}">${glyph} ${label}</button>`}
function stat(label,value,foot,glyph,bg,trend=''){return `<div class="card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon" style="background:${bg}">${glyph}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="positive">${trend}</span>　`:''}${foot}</div></div>`}
function person(name,sub=''){return `<div class="person"><span class="person-avatar">${initials(name)}</span><span><strong>${esc(name)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span></div>`}
function pill(s){let c=/pago|confirmado|ativa|ativo|fechada|frequente|vip/i.test(s)?'green':/vencido|cancelado|baixo|atrasado/i.test(s)?'red':/pendente|aguardando|andamento/i.test(s)?'orange':/novo|utilidade|estética/i.test(s)?'purple':'';return `<span class="pill ${c}">${esc(s)}</span>`}
function sectionHead(title,sub='',action=''){return `<div class="section-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function table(headers,rows){return `<div class="card table-card"><div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}"><div class="empty"><strong>Nenhum registro por aqui ainda</strong>Adicione o primeiro para começar.</div></td></tr>`}</tbody></table></div></div>`}
function schedule(){let start=new Date(today());start.setDate(start.getDate()-1);let days=calendarView==='Dia'?[today()]:Array.from({length:4},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return d});let times=['09:00','10:30','13:00','15:00','16:00'];let data=state.appointments.filter(a=>days.some(d=>d.toISOString().slice(0,10)===a.date));return `<div class="calendar-toolbar"><div class="date-nav"><button data-action="date-prev">‹</button><strong>${calendarView==='Dia'?dateLabel(today()):`${fmtShort(days[0])} – ${fmtShort(days.at(-1))} ${today().getFullYear()}`}</strong><button data-action="date-next">›</button><button class="button small" data-action="date-today">Hoje</button></div><div class="view-toggle"><button data-view="Dia" class="${calendarView==='Dia'?'active':''}">Dia</button><button data-view="Semana" class="${calendarView==='Semana'?'active':''}">Semana</button></div></div><div class="calendar-grid"><div class="cal-head">HORÁRIO</div>${days.map(d=>`<div class="cal-head">${new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(d).replace('.','')}<strong>${d.getDate()}</strong></div>`).join('')}${times.map(time=>`<div class="cal-time">${time}</div>${days.map(d=>{let a=data.find(x=>x.date===d.toISOString().slice(0,10)&&x.time===time);return `<div class="cal-cell" data-action="slot" data-time="${time}" data-date="${d.toISOString().slice(0,10)}">${a?`<div class="appointment ${a.color}" data-appointment="${a.id}"><strong>${esc(a.client)}</strong><span>${esc(a.service)} · ${a.time}</span></div>`:''}</div>`}).join('')}`).join('')}</div><div class="agenda-legend"><span><i class="legend-dot" style="background:var(--primary)"></i>Estética</span><span><i class="legend-dot" style="background:var(--green)"></i>Barbearia</span><span><i class="legend-dot" style="background:var(--orange)"></i>Elétrica & técnica</span><span><i class="legend-dot" style="background:var(--blue)"></i>Outros</span></div>`}
function agendaPage(){if(role==='client')return `${heading('Sua agenda','Escolha um serviço e encontre o melhor horário para você.',btn('Agendar horário','appointment','primary','＋'))}<div class="client-banner"><div><h2>Olá, Mariana 👋</h2><p>Seu próximo horário está confirmado para hoje às 09:00.</p></div><button class="button" data-action="appointment">Agendar outro horário　→</button></div><div class="grid-main-side"><section class="card card-pad">${sectionHead('Próximos horários','Acompanhe seus agendamentos')} ${state.appointments.filter(a=>a.client==='Mariana Costa').map(a=>`<div class="highlight" style="margin-bottom:10px"><div class="highlight-icon">✧</div><div style="flex:1"><strong>${esc(a.service)}</strong><span>${dateLabel(new Date(a.date+'T12:00:00'),{weekday:'short',day:'numeric',month:'short'})} · ${a.time} · ${esc(a.professional)}</span></div>${pill(a.status)}<button class="action-dots" data-action="appointment-menu" data-id="${a.id}">···</button></div>`).join('')||'<div class="empty">Nenhum agendamento futuro.</div>'}</section><section class="card card-pad">${sectionHead('Acesso rápido')}<div class="metric-list"><button class="button" data-page="cobrancas">◉　Minhas cobranças</button><button class="button" data-page="mensagens">✉　Mensagens e comandos</button><button class="button" data-page="clientes">♙　Minha ficha</button></div></section></div><section class="card card-pad">${sectionHead('Escolha um serviço','Opções disponíveis para agendar')}<div class="service-grid">${state.services.slice(0,3).map(serviceCard).join('')}</div></section>`;
return `${heading('Sua agenda, sem complicação',`${dateLabel()} · Organize os horários e acompanhe seu time.`,btn('Novo agendamento','appointment'))}<div class="stats-grid">${stat('Atendimentos hoje',state.appointments.filter(a=>a.date===today().toISOString().slice(0,10)).length,'2 aguardando confirmação','▦','#f0efff')}${stat('Receita prevista',money(state.appointments.filter(a=>a.date===today().toISOString().slice(0,10)).reduce((s,a)=>s+a.price,0)),'Com base nos horários de hoje','↗','#eaf8f2','+12%')}${stat('Clientes do mês',156,'18 novos neste mês','♙','#fff4e9','+8%')}${stat('Ocupação da agenda','78%','Meta mensal: 85%','◷','#eef4ff','+5%')}</div><div class="grid-main-side"><section class="card card-pad">${sectionHead('Visão da agenda','Acompanhe os compromissos da equipe')} ${schedule()}</section><section class="card card-pad">${sectionHead(`Hoje, ${dateLabel(today(),{day:'numeric',month:'long'})}`,'Sua equipe em movimento',`<button class="text-link" data-page="agenda">Ver tudo →</button>`)}<div class="agenda-list">${state.appointments.filter(a=>a.date===today().toISOString().slice(0,10)).sort((a,b)=>a.time.localeCompare(b.time)).map(a=>`<div class="agenda-item"><span class="agenda-time">${a.time}</span><i class="agenda-marker" style="background:${a.color==='green'?'var(--green)':a.color==='orange'?'var(--orange)':a.color==='blue'?'var(--blue)':'var(--primary)'}"></i><div class="agenda-item-body"><strong>${esc(a.client)}</strong><span>${esc(a.service)} · ${esc(a.professional)}</span></div>${pill(a.status)}</div>`).join('')||'<div class="empty">Agenda livre por enquanto.</div>'}</div><button class="button" style="width:100%;margin-top:10px" data-action="appointment">＋ Novo horário</button></section></div><div class="grid-main-side"><section class="card card-pad">${sectionHead('Receita da semana','Entradas previstas por dia',`<span class="date-chip">Esta semana⌄</span>`)}${bars([42,68,51,86,63,96,55],['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'])}</section><section class="card card-pad">${sectionHead('Atenção hoje','Itens que precisam de um olhar')}<div class="metric-list"><div class="highlight"><span class="highlight-icon">◉</span><div style="flex:1"><strong>3 cobranças pendentes</strong><span>R$ 515,00 aguardando</span></div><button class="text-link" data-page="cobrancas">Ver</button></div><div class="highlight"><span class="highlight-icon">▣</span><div style="flex:1"><strong>1 produto com estoque baixo</strong><span>Cabo USB-C 2m · 3 unidades</span></div><button class="text-link" data-page="estoque">Ver</button></div></div></section></div>`}
function bars(values,labels){return `<div class="bar-chart">${values.map((v,i)=>`<div class="bar-col"><em>${i===5?'R$ 2,8k':''}</em><div class="bar" style="--h:${v}%"></div><small>${labels[i]}</small></div>`).join('')}</div>`}
function toolbar(placeholder='Buscar...', extra=''){return `<div class="table-toolbar"><input class="search" id="search" placeholder="⌕　${placeholder}" value="${esc(query)}"><select class="filter-select" id="filter"><option>Todos</option>${extra}</select><span class="toolbar-spacer"></span><button class="button small" data-action="export">↓ Exportar</button></div>`}
function appointmentTable(){let arr=state.appointments.filter(a=>!query||`${a.client} ${a.service} ${a.professional}`.toLowerCase().includes(query.toLowerCase()));return table(['CLIENTE','SERVIÇO','PROFISSIONAL','DATA E HORA','VALOR','STATUS',''],arr.map(a=>`<tr><td>${person(a.client,a.phone||'Cliente cadastrado')}</td><td>${esc(a.service)}</td><td>${esc(a.professional)}</td><td>${dateLabel(new Date(a.date+'T12:00:00'),{day:'2-digit',month:'short'})} · ${a.time}</td><td><b>${money(a.price)}</b></td><td>${pill(a.status)}</td><td><button class="action-dots" data-action="appointment-menu" data-id="${a.id}">···</button></td></tr>`).join(''))}
function chargesPage(){let arr=state.charges.filter(x=>!query||`${x.client} ${x.description}`.toLowerCase().includes(query.toLowerCase()));return `${heading(role==='client'?'Minhas cobranças':'Cobranças',role==='client'?'Consulte pagamentos e valores em aberto.':'Acompanhe os recebimentos e valores em aberto.',role==='manager'?btn('Nova cobrança','charge'): '')}<div class="stats-grid">${stat('Recebido no mês',money(18450),'Até hoje','↗','#eaf8f2','+14%')}${stat('A receber',money(state.charges.filter(x=>x.status==='Pendente').reduce((s,x)=>s+x.value,0)),'3 cobranças em aberto','◷','#fff4e9')}${stat('Vencido',money(state.charges.filter(x=>x.status==='Vencido').reduce((s,x)=>s+x.value,0)),'1 cobrança precisa de atenção','!','#fff0f1')}${stat('Taxa de recebimento','92%','Últimos 30 dias','✓','#eef4ff','+3%')}</div>${toolbar('Buscar por cliente ou serviço')} ${table(['CLIENTE','DESCRIÇÃO','VENCIMENTO','VALOR','FORMA','STATUS',''],arr.map(c=>`<tr><td>${person(c.client)}</td><td>${esc(c.description)}</td><td>${esc(c.due)}</td><td><b>${money(c.value)}</b></td><td>${esc(c.method)}</td><td>${pill(c.status)}</td><td><button class="action-dots" data-action="charge-menu" data-id="${c.id}">···</button></td></tr>`).join(''))}`}
function commandsPage(){return `${heading(role==='client'?'Minhas comandas':'Comandas',role==='client'?'Acompanhe os itens e valores do seu atendimento.':'Abra e feche comandas com serviços e produtos.',role==='manager'?btn('Abrir comanda','command'): '')}<div class="stats-grid">${stat('Em andamento',state.commands.filter(c=>/andamento/i.test(c.status)).length,'Atendimentos abertos','▤','#f0efff')}${stat('Aguardando pagamento',state.commands.filter(c=>/pagamento/i.test(c.status)).length,'Finalize e gere a cobrança','◷','#fff4e9')}${stat('Vendas hoje',money(725),'Comandas fechadas','↗','#eaf8f2','+9%')}${stat('Ticket médio',money(241.7),'Neste mês','◉','#eef4ff')}</div>${toolbar('Buscar comanda ou cliente')} ${table(['COMANDA','CLIENTE','PROFISSIONAL','ITENS','TOTAL','STATUS',''],state.commands.filter(c=>!query||`${c.client} ${c.number}`.toLowerCase().includes(query.toLowerCase())).map(c=>`<tr><td><b>${c.number}</b><small style="display:block;color:var(--muted);margin-top:4px">${c.time}</small></td><td>${person(c.client)}</td><td>${esc(c.professional)}</td><td>${esc(c.items)}</td><td><b>${money(c.total)}</b></td><td>${pill(c.status)}</td><td><button class="button small" data-action="command-close" data-id="${c.id}">${c.status==='Fechada'?'Detalhes':'Fechar'}</button></td></tr>`).join(''))}`}
function messagesPage(){return `${heading(role==='client'?'Mensagens e comandos':'Mensagens pré-definidas',role==='client'?'Veja orientações e mensagens sobre seus atendimentos.':'Responda mais rápido com modelos organizados por etapa.',role==='manager'?btn('Criar mensagem','message'): '')}<div class="highlight" style="margin-bottom:16px"><div class="highlight-icon">✉</div><div><strong>WhatsApp Business API</strong><span>Conecte um número oficial nas configurações para enviar mensagens automáticas. Modelos enviados fora da janela de atendimento podem exigir aprovação da Meta.</span></div>${role==='manager'?`<button class="text-link" data-page="configuracoes">Configurar →</button>`:''}</div><div class="service-grid">${state.messages.map(m=>`<article class="card service-card"><div class="service-top"><span class="service-symbol">✉</span>${pill(m.type)}</div><h4>${esc(m.title)}</h4><p style="min-height:56px">${esc(m.text)}</p><div class="service-details"><small>Variáveis: {{nome}}, {{data}}, {{hora}}</small><button class="button small soft" data-action="copy-message" data-id="${m.id}">Copiar</button></div>${role==='manager'?`<div style="display:flex;gap:6px;margin-top:9px"><button class="button small" data-action="edit-message" data-id="${m.id}">Editar</button><button class="button small" data-action="message-send" data-id="${m.id}">Pré-visualizar</button></div>`:''}</article>`).join('')}</div>`}
function clientsPage(){if(role==='client')return `${heading('Minha ficha','Mantenha seus dados e informações de atendimento atualizados.',btn('Editar meus dados','client-edit','primary','✎'))}<div class="page-heading"><div><div class="eyebrow">RELACIONAMENTO</div><h1>Clientes & anamneses</h1><p>Histórico de atendimento e fichas adequadas a cada tipo de serviço.</p></div><div class="heading-actions">${btn('Novo cliente','client')}</div></div><div class="client-banner"><div><h2>Base de clientes</h2><p>Cadastro, recorrência e informações de atendimento em um só lugar.</p></div><span class="pill green">${state.clients.length} clientes</span></div><div class="tab-row">${['Todos','Clientes','Anamneses'].map(t=>`<button class="${clientTab===t?'active':''}" data-clienttab="${t}">${t}</button>`).join('')}</div>${clientTab==='Anamneses'?`<div class="service-grid">${state.anamneses.map(a=>`<article class="card service-card"><div class="service-top"><span class="service-symbol">▤</span>${pill(a.category)}</div><h4>${esc(a.name)}</h4><p>${esc(a.updated)} · Acesso restrito à equipe autorizada</p><div class="service-details"><small>Dados de atendimento</small><button class="button small soft" data-action="anamnesis-edit" data-id="${a.id}">Abrir ficha</button></div></article>`).join('')}${btn('Nova ficha','anamnesis','primary','＋')}</div>`:`${role==='manager'?toolbar('Buscar nome, telefone ou e-mail'):''}${table(['CLIENTE','CONTATO','ÚLTIMO ATENDIMENTO','VISITAS','TOTAL GASTO','PERFIL',''],state.clients.filter(c=>(!query||`${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(query.toLowerCase()))&&(role!=='client'||c.name==='Mariana Costa')).map(c=>`<tr><td>${person(c.name,'Desde 2025')}</td><td>${esc(c.phone)}<small style="display:block;color:var(--muted);margin-top:3px">${esc(c.email)}</small></td><td>${esc(c.last)}</td><td>${c.visits}</td><td><b>${money(c.spent)}</b></td><td>${pill(c.tag)}</td><td><button class="action-dots" data-action="client-menu" data-id="${c.id}">···</button></td></tr>`).join(''))}`}`}
function serviceCard(s){return `<article class="card service-card"><div class="service-top"><span class="service-symbol">${esc(s.icon)}</span>${pill(s.category)}</div><h4>${esc(s.name)}</h4><p>${esc(s.desc)}</p><div class="service-details"><span><b class="service-price">${money(s.price)}</b><small> / ${s.duration} min</small></span><button class="button small ${role==='client'?'primary':'soft'}" data-action="${role==='client'?'book-service':'edit-service'}" data-id="${s.id}">${role==='client'?'Agendar':'Editar'}</button></div></article>`}
function servicesPage(){let packages=serviceTab==='Pacotes';return `${heading(role==='client'?'Serviços e pacotes':'Serviços & pacotes',role==='client'?'Conheça as opções e escolha seu próximo atendimento.':'Configure serviços com duração, categoria e preço claros.',role==='manager'?btn(packages?'Novo pacote':'Novo serviço',packages?'package':'service'): '')}<div class="tab-row"><button class="${!packages?'active':''}" data-servicetab="Serviços">Serviços</button><button class="${packages?'active':''}" data-servicetab="Pacotes">Pacotes <span class="pill purple">${state.packages.length}</span></button></div>${!packages?`<div class="table-toolbar"><input class="search" id="search" placeholder="⌕　Buscar serviço..." value="${esc(query)}"><select class="filter-select" id="filter"><option>Todos</option>${['Estética','Barbearia','Elétrica','Eletrônicos','Eventos'].map(x=>`<option>${x}</option>`).join('')}</select><span class="toolbar-spacer"></span><span class="pill purple">${state.services.length} serviços ativos</span></div><div class="service-grid">${state.services.filter(s=>(!query||s.name.toLowerCase().includes(query.toLowerCase()))&&(filter==='Todos'||s.category===filter)).map(serviceCard).join('')}</div>`:`<div class="highlight" style="margin-bottom:14px"><div class="highlight-icon">✦</div><div><strong>Pacotes e créditos pré-pagos</strong><span>Combine sessões, preço total e validade. O saldo pode ser acompanhado na ficha do cliente.</span></div></div><div class="service-grid">${state.packages.map(p=>`<article class="card service-card"><div class="service-top"><span class="service-symbol">♧</span>${pill(p.category)}</div><h4>${esc(p.name)}</h4><p>${esc(p.sessions)} sessões de ${esc(p.service||'serviços selecionados')}. Controle o saldo a cada atendimento.</p><div class="service-details"><span><b class="service-price">${money(p.price)}</b><small> / pacote</small></span><span class="pill green">${money(p.price/p.sessions)} por sessão</span></div></article>`).join('')}</div>`}`}
function stockPage(){return `${heading('Produtos & estoque','Controle entradas, saídas e níveis de reposição.',btn('Adicionar produto','product'))}<div class="stats-grid">${stat('Produtos cadastrados',state.products.length,'Em todas as categorias','▣','#f0efff')}${stat('Valor em estoque',money(state.products.reduce((s,p)=>s+p.stock*p.cost,0)),'Custo de aquisição','◉','#eaf8f2')}${stat('Estoque baixo',state.products.filter(p=>p.stock<=p.min).length,'Abaixo do mínimo configurado','!','#fff4e9')}${stat('Vendas de produtos',money(2840),'Neste mês','↗','#eef4ff','+11%')}</div>${toolbar('Buscar produto ou SKU','<option>Estética</option><option>Barbearia</option><option>Elétrica</option><option>Eletrônicos</option>')} ${table(['PRODUTO','SKU','CATEGORIA','CUSTO','PREÇO','EM ESTOQUE','STATUS',''],state.products.filter(p=>!query||`${p.name} ${p.sku}`.toLowerCase().includes(query.toLowerCase())).map(p=>`<tr><td>${person(p.name)}</td><td>${p.sku}</td><td>${pill(p.category)}</td><td>${money(p.cost)}</td><td><b>${money(p.price)}</b></td><td><b>${p.stock}</b> un.</td><td>${p.stock<=p.min?pill('Baixo'):pill('Disponível')}</td><td><button class="button small" data-action="stock-adjust" data-id="${p.id}">Ajustar</button></td></tr>`).join(''))}`}
function expensesPage(){return `${heading('Despesas','Organize custos fixos e variáveis e acompanhe vencimentos.',btn('Nova despesa','expense'))}<div class="stats-grid">${stat('Despesas no mês',money(8269),'Lançadas em setembro','↘','#fff4e9')}${stat('Despesas pagas',money(5680),'68,7% do total','✓','#eaf8f2')}${stat('A vencer',money(2589),'Próximos 10 dias','◷','#eef4ff')}${stat('Despesas recorrentes','4 itens','Gerencie seus custos fixos','↻','#f0efff')}</div>${toolbar('Buscar despesa')} ${table(['DESPESA','CATEGORIA','VENCIMENTO','VALOR','STATUS',''],state.expenses.filter(e=>!query||e.title.toLowerCase().includes(query.toLowerCase())).map(e=>`<tr><td>${person(e.title)}</td><td>${pill(e.category)}</td><td>${e.due}</td><td><b>${money(e.value)}</b></td><td>${pill(e.status)}</td><td><button class="action-dots" data-action="expense-menu" data-id="${e.id}">···</button></td></tr>`).join(''))}`}
function teamPage(){return `${heading('Profissionais & comissão','Acompanhe agenda, repasses e desempenho da equipe.',btn('Adicionar profissional','professional'))}<div class="stats-grid">${stat('Profissionais ativos',state.professionals.length,'Em todas as áreas','♧','#f0efff')}${stat('Serviços no mês',115,'Finalizados pela equipe','▦','#eaf8f2','+13%')}${stat('Comissões previstas',money(8345),'Valores a repassar','◷','#fff4e9')}${stat('Receita da equipe',money(23120),'Neste mês','↗','#eef4ff','+16%')}</div>${table(['PROFISSIONAL','ESPECIALIDADE','COMISSÃO','ATENDIMENTOS','RECEITA GERADA','STATUS',''],state.professionals.map(p=>`<tr><td>${person(p.name,'Membro da equipe')}</td><td>${esc(p.role)}</td><td><b>${p.commission}%</b></td><td>${p.appointments}</td><td><b>${money(p.revenue)}</b></td><td>${pill(p.status)}</td><td><button class="button small" data-action="professional-edit" data-id="${p.id}">Detalhes</button></td></tr>`).join(''))}`}
function performancePage(){return `${heading('Performance','Indicadores para acompanhar a saúde da operação.','<select class="filter-select"><option>Este mês</option><option>Últimos 30 dias</option><option>Este trimestre</option></select>')}<div class="stats-grid">${stat('Faturamento bruto',money(28450),'Meta mensal: R$ 32.000','↗','#eaf8f2','+18,4%')}${stat('Taxa de ocupação','78,6%','Meta: 85%','◷','#f0efff','+6,2%')}${stat('Ticket médio',money(247.4),'Por atendimento','◉','#eef4ff','+4,8%')}${stat('Retorno de clientes','64%','Voltaram em até 60 dias','♙','#fff4e9','+9%')}</div><div class="grid-main-side"><section class="card card-pad">${sectionHead('Faturamento por semana','Comparativo do mês atual')} ${bars([42,68,51,86,63,96,55],['S1','S2','S3','S4','S5','S6','S7'])}</section><section class="card card-pad">${sectionHead('Atendimentos por categoria')}<div style="display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:8px"><div class="donut"><div class="donut-center"><strong>115</strong><small>serviços</small></div></div><div class="metric-list"><div class="metric-row"><span>Estética</span><b>48%</b></div><div class="metric-row"><span>Barbearia</span><b>27%</b></div><div class="metric-row"><span>Técnicos</span><b>15%</b></div><div class="metric-row"><span>Eventos</span><b>10%</b></div></div></div></section></div><section class="card card-pad">${sectionHead('Destaques da equipe','Desempenho no período')} ${table(['PROFISSIONAL','ATENDIMENTOS','RECEITA','OCUPAÇÃO'],state.professionals.map(p=>`<tr><td>${person(p.name,p.role)}</td><td>${p.appointments}</td><td><b>${money(p.revenue)}</b></td><td><div style="display:flex;align-items:center;gap:8px"><div class="progress" style="width:110px"><span style="width:${Math.min(95,55+p.appointments)}%"></span></div>${Math.min(95,55+p.appointments)}%</div></td></tr>`).join(''))}</section>`}
function financePage(){return `${heading('Resumo financeiro','Visão consolidada de entradas, despesas e resultado.','<select class="filter-select"><option>Setembro 2026⌄</option><option>Agosto 2026</option></select><button class="button" data-action="export">↓ Exportar relatório</button>')}<div class="stats-grid">${stat('Receita bruta',money(28450),'Serviços e produtos','↗','#eaf8f2','+18,4%')}${stat('Despesas',money(8269),'Custos operacionais','↘','#fff4e9')}${stat('Comissões',money(8345),'Repasses previstos','♧','#f0efff')}${stat('Resultado estimado',money(11836),'41,6% de margem','◉','#eef4ff','+12,1%')}</div><div class="grid-main-side"><section class="card card-pad">${sectionHead('Entradas e saídas','Por semana no mês atual')} ${bars([48,65,54,92,67,78,61],['S1','S2','S3','S4','S5','S6','S7'])}</section><section class="card card-pad">${sectionHead('Composição do faturamento')}<div class="metric-list"><div class="metric-row"><span>Serviços</span><b>R$ 22.650 · 79,6%</b></div><div class="progress"><span style="width:80%"></span></div><div class="metric-row"><span>Produtos</span><b>R$ 3.240 · 11,4%</b></div><div class="progress"><span style="width:35%;background:var(--green)"></span></div><div class="metric-row"><span>Pacotes</span><b>R$ 2.560 · 9,0%</b></div><div class="progress"><span style="width:28%;background:var(--orange)"></span></div></div></section></div><section class="card card-pad">${sectionHead('Últimas movimentações','Conciliação de recebimentos e despesas')} ${table(['DATA','DESCRIÇÃO','TIPO','CATEGORIA','VALOR'],[`<tr><td>30 set</td><td>${person('Limpeza de pele','Mariana Costa')}</td><td>${pill('Entrada')}</td><td>Serviço</td><td class="positive">+ R$ 180,00</td></tr>`,`<tr><td>29 set</td><td>${person('Compra de produtos','Fornecedor Beleza')}</td><td>${pill('Saída')}</td><td>Estoque</td><td style="color:var(--red)">− R$ 680,00</td></tr>`,`<tr><td>28 set</td><td>${person('Corte + barba','Lucas Martins')}</td><td>${pill('Entrada')}</td><td>Serviço</td><td class="positive">+ R$ 95,00</td></tr>`])}</section>`}
function loyaltyPage(){return `${heading('Melhores clientes','Reconheça a recorrência e cuide dos relacionamentos.','<select class="filter-select"><option>Últimos 90 dias</option><option>Este ano</option></select>')}<div class="stats-grid">${stat('Clientes ativos',156,'Nos últimos 90 dias','♙','#f0efff')}${stat('Clientes recorrentes',98,'62,8% da base','↻','#eaf8f2','+8%')}${stat('Ticket médio VIP',money(486),'Clientes mais fiéis','♛','#fff4e9','+15%')}${stat('Aniversários este mês',12,'Uma oportunidade de carinho','♡','#eef4ff')}</div><div class="card card-pad">${sectionHead('Clientes em destaque','Ordenados por valor total e frequência')} ${table(['#','CLIENTE','ATENDIMENTOS','ÚLTIMA VISITA','TOTAL INVESTIDO','PERFIL'],[...state.clients].sort((a,b)=>b.spent-a.spent).map((c,i)=>`<tr><td><b>${String(i+1).padStart(2,'0')}</b>　${i===0?'♛':''}</td><td>${person(c.name,c.phone)}</td><td>${c.visits}</td><td>${c.last}</td><td><b>${money(c.spent)}</b></td><td>${pill(i<2?'VIP':'Frequente')}</td></tr>`).join(''))}</div>`}
function settingsPage(){let tabs=['Geral','Agenda','Notificações','WhatsApp API','Acesso e perfis'];let body=settingsTab==='Geral'?`<div class="setting-row"><div><strong>Nome do estabelecimento</strong><p>Como seu negócio aparece para os clientes.</p></div><input class="search" value="Ateliê Oliveira" style="max-width:220px"></div><div class="setting-row"><div><strong>Segmentos atendidos</strong><p>Use categorias para organizar serviços e relatórios.</p></div><span class="pill purple">Estética · Barbearia · Eventos · Técnico</span></div><div class="setting-row"><div><strong>Moeda e fuso horário</strong><p>Preferências regionais do seu negócio.</p></div><b style="font-size:10px">BRL · Brasília (UTC−3)</b></div><div class="setting-row"><div><strong>Tema escuro</strong><p>Escolha a aparência do Agenda OL.</p></div><button class="switch ${theme==='dark'?'on':''}" data-action="theme"></button></div>`:settingsTab==='Agenda'?`<div class="setting-row"><div><strong>Duração padrão dos horários</strong><p>Usada como sugestão ao criar um agendamento.</p></div><select class="filter-select"><option>30 minutos</option><option selected>30 minutos</option><option>60 minutos</option></select></div><div class="setting-row"><div><strong>Intervalo entre atendimentos</strong><p>Tempo reservado para preparação e organização.</p></div><select class="filter-select"><option>Sem intervalo</option><option>10 minutos</option><option>15 minutos</option></select></div><div class="setting-row"><div><strong>Permitir autoagendamento</strong><p>Clientes podem escolher horários disponíveis.</p></div><button class="switch on" data-action="switch"></button></div>`:settingsTab==='Notificações'?`<div class="setting-row"><div><strong>Confirmação de agendamento</strong><p>Enviar instruções após reservar um horário.</p></div><button class="switch on" data-action="switch"></button></div><div class="setting-row"><div><strong>Lembrete 24 horas antes</strong><p>Reduza faltas com um lembrete no dia anterior.</p></div><button class="switch on" data-action="switch"></button></div><div class="setting-row"><div><strong>Aviso de cobrança vencida</strong><p>Alertar a equipe sobre pagamentos em atraso.</p></div><button class="switch" data-action="switch"></button></div>`:settingsTab==='WhatsApp API'?`<div class="highlight" style="margin-bottom:15px"><div class="highlight-icon">✉</div><div><strong>Conecte a WhatsApp Business Platform</strong><span>Automatize confirmações e lembretes pela API oficial da Meta.</span></div></div><div class="setting-row"><div><strong>Status da conexão</strong><p>Suas credenciais ficam protegidas no servidor quando integrado.</p></div>${pill('Não conectado')}</div><div class="form-grid" style="padding-top:15px"><div class="field"><label>Phone Number ID</label><input placeholder="ID fornecido pela Meta"></div><div class="field"><label>WhatsApp Business Account ID</label><input placeholder="WABA ID"></div><div class="field full"><label>Token de acesso</label><input type="password" placeholder="Configure no backend seguro"></div><div class="field full"><small style="color:var(--muted);line-height:1.5">Este protótipo não transmite mensagens nem armazena credenciais. Uma integração real requer backend seguro, webhook e configuração da conta empresarial. Mensagens proativas podem depender de modelos aprovados.</small></div></div><button class="button primary" style="margin-top:14px" data-action="whatsapp-connect">Salvar configuração</button>`:`<div class="setting-row"><div><strong>Perfil de acesso do cliente</strong><p>Agenda, cobranças, comandas, cadastro, anamneses e serviços.</p></div>${pill('Ativo')}</div><div class="setting-row"><div><strong>Perfil de gestor</strong><p>Financeiro, equipe, estoque, relatórios e configurações.</p></div>${pill('Administrador')}</div><div class="setting-row"><div><strong>Dados de anamnese</strong><p>Informações de saúde são dados sensíveis. Restrinja acesso por função e registre finalidade.</p></div>${pill('Acesso restrito')}</div>`;return `${heading('Configurações','Personalize seu espaço de trabalho e integrações.')}<div class="settings-layout"><nav class="card settings-nav">${tabs.map(t=>`<button class="${settingsTab===t?'active':''}" data-settingtab="${t}">${t==='WhatsApp API'?'✉　':t==='Acesso e perfis'?'♙　':'⚙　'}${t}</button>`).join('')}</nav><section class="card card-pad"><div class="section-head"><div><h3>${settingsTab}</h3><p>Preferências do Agenda OL</p></div>${settingsTab!=='WhatsApp API'?'<button class="button primary small" data-action="save-settings">Salvar alterações</button>':''}</div>${body}</section></div>`}
function renderPage(){switch(page){case'agenda':return agendaPage();case'cobrancas':return chargesPage();case'comandas':return commandsPage();case'mensagens':return messagesPage();case'clientes':return clientsPage();case'servicos':return servicesPage();case'estoque':return stockPage();case'despesas':return expensesPage();case'equipe':return teamPage();case'performance':return performancePage();case'financeiro':return financePage();case'fidelidade':return loyaltyPage();case'configuracoes':return settingsPage();default:return agendaPage()}}
function render(){renderShell()}
function field(name,label,type='text',placeholder='',opts=[]){if(type==='select')return `<div class="field"><label>${label}</label><select name="${name}" required>${opts.map(o=>`<option>${esc(o)}</option>`).join('')}</select></div>`;if(type==='textarea')return `<div class="field full"><label>${label}</label><textarea name="${name}" placeholder="${placeholder}"></textarea></div>`;return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" ${name==='name'||name==='client'||name==='title'?'required':''}></div>`}
function openModal(title,body,submit='Salvar'){modal={title,body,submit};let el=document.createElement('div');el.className='modal-backdrop';el.id='modal';el.innerHTML=`<div class="modal"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-action="close-modal">×</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button primary" type="submit">${submit}</button></div></form></div>`;document.body.append(el);}
function formModal(type,id){let obj=id?findItem(type,id):{};let body='';switch(type){case'appointment':body=`<div class="form-grid">${field('client','Cliente','text','Nome do cliente')}${field('service','Serviço','select','',['Limpeza de pele','Corte + barba','Manutenção elétrica','Ensaio fotográfico','Design de sobrancelha','Diagnóstico de notebook'])}${field('professional','Profissional','select','',['Camila Rocha','Rafael Lima','João Pedro','Marcos Vieira'])}${field('date','Data','date')}${field('time','Horário','time')}${field('duration','Duração (min)','number','30')}${field('price','Valor (R$)','number','0')}${field('status','Status','select','',['Confirmado','Aguardando','Em atendimento'])}</div>`;break;case'client':body=`<div class="form-grid">${field('name','Nome completo','text','Nome e sobrenome')}${field('phone','Telefone','tel','(00) 00000-0000')}${field('email','E-mail','email','email@exemplo.com')}${field('tag','Perfil','select','',['Novo','Frequente','VIP'])}</div>`;break;case'service':body=`<div class="form-grid">${field('name','Nome do serviço','text','Ex.: Avaliação técnica')}${field('category','Categoria','select','',['Estética','Barbearia','Elétrica','Eletrônicos','Eventos'])}${field('duration','Duração (minutos)','number','60')}${field('price','Preço (R$)','number','0')}${field('desc','Descrição','textarea','Explique o que está incluso')}</div>`;break;case'package':body=`<div class="form-grid">${field('name','Nome do pacote','text','Ex.: Ritual de autocuidado')}${field('category','Categoria','select','',['Estética','Barbearia','Elétrica','Eletrônicos','Eventos'])}${field('service','Serviço incluído','select','',['Limpeza de pele','Corte + barba','Manutenção elétrica','Ensaio fotográfico','Design de sobrancelha'])}${field('sessions','Quantidade de sessões','number','4')}${field('price','Preço total (R$)','number','0')}</div>`;break;case'product':body=`<div class="form-grid">${field('name','Nome do produto','text','Nome do produto')}${field('sku','SKU','text','COD-001')}${field('category','Categoria','select','',['Estética','Barbearia','Elétrica','Eletrônicos'])}${field('stock','Estoque atual','number','0')}${field('min','Estoque mínimo','number','3')}${field('cost','Custo unitário (R$)','number','0')}${field('price','Preço de venda (R$)','number','0')}</div>`;break;case'expense':body=`<div class="form-grid">${field('title','Descrição','text','Ex.: Conta de energia')}${field('category','Categoria','select','',['Estrutura','Estoque','Serviços','Marketing','Pessoal','Impostos'])}${field('value','Valor (R$)','number','0')}${field('due','Vencimento','date')}${field('status','Status','select','',['Pendente','Pago'])}</div>`;break;case'professional':body=`<div class="form-grid">${field('name','Nome','text','Nome do profissional')}${field('role','Especialidade','text','Ex.: Esteticista')}${field('commission','Comissão (%)','number','45')}${field('status','Status','select','',['Ativo','Inativo'])}</div>`;break;case'charge':body=`<div class="form-grid">${field('client','Cliente','text','Nome do cliente')}${field('description','Descrição','text','Serviço ou produto')}${field('value','Valor (R$)','number','0')}${field('due','Vencimento','date')}${field('method','Forma de pagamento','select','',['Pix','Cartão','Dinheiro','Transferência'])}${field('status','Status','select','',['Pendente','Pago','Vencido'])}</div>`;break;case'command':body=`<div class="form-grid">${field('client','Cliente','text','Nome do cliente')}${field('professional','Profissional','text','Quem atende')}${field('items','Itens da comanda','text','Serviços e produtos')}${field('total','Total (R$)','number','0')}</div>`;break;case'message':body=`<div class="form-grid">${field('title','Nome do modelo','text','Ex.: Lembrete de retorno')}${field('type','Categoria','select','',['Utilidade','Relacionamento'])}${field('text','Mensagem','textarea','Use {{nome}}, {{data}} e {{hora}}')}</div>`;break;case'anamnesis':body=`<div class="form-grid">${field('name','Nome da ficha','text','Ex.: Ficha de atendimento inicial')}${field('category','Categoria','select','',['Estética','Barbearia','Elétrica','Eletrônicos','Eventos'])}${field('notes','Observações','textarea','Perguntas e informações necessárias')}</div><p style="font-size:9px;color:var(--muted);margin-top:10px">Formulários que coletam dados de saúde devem ter acesso restrito e finalidade clara.</p>`;break;default:body='<p>Informe os dados necessários.</p>'}openModal(id?`Editar ${type==='service'?'serviço':type==='professional'?'profissional':'cadastro'}`:({appointment:'Novo agendamento',client:'Novo cliente',service:'Novo serviço',package:'Novo pacote',product:'Adicionar produto',expense:'Nova despesa',professional:'Novo profissional',charge:'Nova cobrança',command:'Abrir comanda',message:'Nova mensagem pré-definida',anamnesis:'Criar ficha de anamnese'}[type]),body,id?'Atualizar':'Salvar');modal.type=type;modal.id=id;if(id)for(const [k,v] of Object.entries(obj)){let input=$(`#modal-form [name="${k}"]`);if(input&&input.type!=='date')input.value=v??'';else if(input&&input.type==='date'&&/^\d{4}-\d{2}-\d{2}$/.test(v))input.value=v}}
function findItem(type,id){return ({appointment:state.appointments,client:state.clients,service:state.services,product:state.products,expense:state.expenses,professional:state.professionals,charge:state.charges,command:state.commands,message:state.messages,anamnesis:state.anamneses}[type]||[]).find(x=>x.id===Number(id))||{}}
function saveForm(fd){let type=modal.type,id=modal.id;let d=Object.fromEntries(fd.entries());if(type==='anamnesisResponse'){anamnesisResponses.push({template:id,client:'Mariana Costa',data:d,created:new Date().toISOString()});$('#modal')?.remove();toast('Ficha preenchida nesta demonstração. A resposta não foi gravada no navegador.');return}let arr=({appointment:'appointments',client:'clients',service:'services',package:'packages',product:'products',expense:'expenses',professional:'professionals',charge:'charges',command:'commands',message:'messages',anamnesis:'anamneses'});if(!arr[type])return;for(let k of ['price','duration','sessions','stock','min','cost','commission','value','total'])if(d[k]!==undefined)d[k]=Number(d[k]);if(type==='appointment'){let begin=m=>{let [h,min]=String(m||'0:0').split(':').map(Number);return h*60+min},start=begin(d.time),end=start+(Number(d.duration)||30);let conflict=state.appointments.some(x=>x.id!==Number(id)&&x.date===d.date&&x.professional===d.professional&&start<begin(x.time)+(Number(x.duration)||30)&&begin(x.time)<end);if(conflict){toast('Esse profissional já tem um atendimento nesse horário.');return}d.id=id||Date.now();d.color=d.service?.toLowerCase().includes('corte')?'green':d.service?.toLowerCase().includes('elétrica')?'orange':'purple';if(!d.date)d.date=today().toISOString().slice(0,10);state.appointments=state.appointments.filter(x=>x.id!==Number(id));state.appointments.push(d)}else if(type==='command'){d.id=id||Date.now();d.number=`#${1049+state.commands.length}`;d.status='Em andamento';d.time='Agora';state.commands.unshift(d)}else{d.id=id||Date.now();let key=arr[type];state[key]=state[key].filter(x=>x.id!==Number(id));if(type==='service')d.icon='✦';if(type==='expense'&&d.due)d.due=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(d.due+'T12:00:00'));if(type==='client'){d.last='Novo cadastro';d.visits=0;d.spent=0}if(type==='product'&&!d.sku)d.sku=`OL-${String(d.id).slice(-3)}`;state[key].unshift(d)}persist();$('#modal')?.remove();toast('Informações salvas com sucesso.');render()}
function action(e){let a=e.target.closest('[data-action]');if(!a)return;let act=a.dataset.action,id=a.dataset.id;if(act==='theme'){theme=theme==='light'?'dark':'light';localStorage.setItem('agendaOLBetaTheme',theme);render()}else if(act==='menu')$('#sidebar').classList.toggle('open');else if(act==='appointment'||act==='charge'||act==='client'||act==='service'||act==='package'||act==='product'||act==='expense'||act==='professional'||act==='command'||act==='message'||act==='anamnesis')formModal(act);else if(act==='book-service'){formModal('appointment');let s=findItem('service',id);setTimeout(()=>{let q=$('#modal-form select[name="service"]');if(q)q.value=s.name},0)}else if(act==='edit-service')formModal('service',id);else if(act==='client-edit')formModal('client',1);else if(act==='close-modal')$('#modal')?.remove();else if(act==='date-prev'||act==='date-next'){dayOffset+=act==='date-prev'?-1:1;render()}else if(act==='date-today'){dayOffset=0;render()}else if(act==='slot'){formModal('appointment');setTimeout(()=>{let d=a.dataset.date,t=a.dataset.time;$('#modal-form [name=date]').value=d;$('#modal-form [name=time]').value=t},0)}else if(act==='appointment-menu'){let ap=findItem('appointment',id);let choice=prompt(`Agendamento de ${ap.client}\nDigite: 1 para marcar como concluído, 2 para cancelar`);if(choice==='1'){ap.status='Concluído';save();toast('Atendimento concluído.')}if(choice==='2'){ap.status='Cancelado';save();toast('Agendamento cancelado.')}}else if(act==='charge-menu'){let x=findItem('charge',id);if(confirm(`Marcar cobrança de ${money(x.value)} como paga?`)){x.status='Pago';save();toast('Cobrança atualizada.')}}else if(act==='command-close'){let x=findItem('command',id);if(x.status==='Fechada')return toast('Esta comanda já está fechada.');x.status='Fechada';state.charges.unshift({id:Date.now(),client:x.client,description:`Comanda ${x.number}`,value:x.total,due:dateLabel(today(),{day:'2-digit',month:'short',year:'numeric'}),status:'Pendente',method:'Pix'});save();toast('Comanda fechada e cobrança gerada.')}else if(act==='stock-adjust'){let p=findItem('product',id),v=prompt(`Estoque de ${p.name}: ${p.stock} un.\nInforme a quantidade final:`);if(v!==null&&!isNaN(+v)){p.stock=+v;save();toast('Estoque atualizado.')}}else if(act==='expense-menu'){let x=findItem('expense',id);x.status=x.status==='Pago'?'Pendente':'Pago';save();toast('Status da despesa atualizado.')}else if(act==='professional-edit')formModal('professional',id);else if(act==='copy-message'){let m=findItem('message',id);navigator.clipboard?.writeText(m.text).then(()=>toast('Mensagem copiada.')).catch(()=>toast(m.text))}else if(act==='edit-message')formModal('message',id);else if(act==='message-send'){let m=findItem('message',id);openModal('Prévia da mensagem',`<div class="highlight"><div class="highlight-icon">✉</div><div><strong>${esc(m.title)}</strong><span>${esc(m.text)}</span></div></div><p style="font-size:10px;color:var(--muted);margin-top:12px">Para enviar automaticamente, conecte a WhatsApp Business API nas configurações do gestor.</p>`,'Entendi')}else if(act==='support')openModal('Suporte Agenda OL','<p style="font-size:12px;line-height:1.7;color:var(--muted)">Conte com a gente. Envie sua dúvida para <b>contato@orbelabz.com</b> ou consulte a central de ajuda. Em uma implantação real, este espaço pode ser ligado ao canal de atendimento da sua equipe.</p>','Fechar');else if(act==='profile')toast('Perfil do usuário');else if(act==='notifications')toast('Você está em dia com as notificações.');else if(act==='export'){let csv='Cliente,Serviço,Profissional,Data,Horário,Valor,Status\n'+state.appointments.map(x=>`"${x.client}","${x.service}","${x.professional}",${x.date},${x.time},${x.price},${x.status}`).join('\n');let link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download='agenda-ol-relatorio.csv';link.click();URL.revokeObjectURL(link.href);toast('Relatório exportado.')}else if(act==='packages'){serviceTab='Pacotes';render()}else if(act==='switch'){a.classList.toggle('on')}else if(act==='save-settings')toast('Configurações salvas.');else if(act==='whatsapp-connect'){toast('Configure a API quando o backend seguro estiver disponível.')}else if(act==='anamnesis-edit'){let x=findItem('anamnesis',id);if(role==='client'){openModal(x.name,`<div class="form-grid">${field('goal','O que você gostaria de tratar ou informar?','textarea','Conte, se quiser, o que é importante para seu atendimento.')}${field('preferences','Preferências e cuidados','textarea','Informe preferências relevantes ao serviço.')}${field('consent','Li o aviso sobre meus dados','select','',['Sim, desejo enviar esta ficha'])}</div><p style="font-size:9px;color:var(--muted);margin-top:10px">Nesta demonstração, as respostas não são enviadas nem armazenadas. Em produção, anamnese exige controles de acesso e proteção de dados sensíveis.</p>`,'Enviar ficha');modal.type='anamnesisResponse';modal.id=id}else{openModal(x.name,`<div class="highlight"><div class="highlight-icon">▤</div><div><strong>${esc(x.category)} · Ficha de atendimento</strong><span>Acesso restrito à equipe responsável. Registre apenas informações pertinentes ao serviço.</span></div></div><div class="form-grid" style="margin-top:15px">${field('notes','Observações do cliente','textarea','Anotações de atendimento')}${field('consent','Autorização de tratamento de dados','select','',['Aguardando registro','Registrada'])}</div>`,'Salvar ficha')}}
}
document.addEventListener('click',e=>{let p=e.target.closest('[data-page]');if(p){goto(p.dataset.page);return}let r=e.target.closest('[data-role]');if(r){role=r.dataset.role;if(role==='client'&&!['agenda','cobrancas','comandas','mensagens','clientes','servicos'].includes(page))page='agenda';render();return}let v=e.target.closest('[data-view]');if(v){calendarView=v.dataset.view;render();return}let st=e.target.closest('[data-settingtab]');if(st){settingsTab=st.dataset.settingtab;render();return}let ct=e.target.closest('[data-clienttab]');if(ct){clientTab=ct.dataset.clienttab;render();return}let sv=e.target.closest('[data-servicetab]');if(sv){serviceTab=sv.dataset.servicetab;query='';render();return}action(e)});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;let pos=e.target.selectionStart;render();let n=$('#search');n?.focus();n?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id==='modal-form'){e.preventDefault();if(modal?.submit==='Entendi'){$('#modal')?.remove();return}saveForm(new FormData(e.target))}});
render();
